import type { NextConfig } from "next";

/**
 * The four package pages (yourkey.app/sales, /time, /communication, /leadership) are static HTML in
 * public/packages/, generated by the app repo (yourkey-app: scripts/web/package-pages.ts) from the
 * same claims-checked copy the in-app paywalls use. Do not edit those files here — regenerate them.
 * Until the production purchase link is set in the app repo, they are previews: no checkout, noindex.
 */
const PACKAGE_PAGES = ["sales", "time", "communication", "leadership"];
/**
 * Since 2026-10-13 the same generator writes the join page (the buyer sets up their Your Key account,
 * then the checkout opens keyed to it; app/api/account/route.ts makes the account) and the page the
 * checkout returns to, which says how to sign in on the iPhone.
 */
const ACCOUNT_PAGES = ["join", "welcome"];

/**
 * The Studio (2026-10-20): Tushar's private recorder for filming the seminars on his iPhone, the words on
 * its screen and every kept take straight to his Google Drive. public/studio/index.html holds no scripts
 * (they are pasted in and stay on his phone) and asks Google only for drive.file. Since 2026-10-21 it is
 * locked: proxy.ts sends a password page instead until the phone holds the Studio's cookie
 * (lib/studioLock.ts; the password is STUDIO_PASSWORD in Vercel, never in this public repository).
 */
const STUDIO = { source: "/studio", destination: "/studio/index.html" };

const nextConfig: NextConfig = {
  async rewrites() {
    return [...[...PACKAGE_PAGES, ...ACCOUNT_PAGES].map((id) => ({ source: `/${id}`, destination: `/packages/${id}.html` })), STUDIO];
  },
  /* The July site's /seminar and /mastermind described a seminar and an AI council the app no longer
     has under those names (rebuilt 2026-10-04). Old links land on what is true today. */
  async redirects() {
    return [
      { source: "/seminar", destination: "/packages", permanent: true },
      { source: "/mastermind", destination: "/tools", permanent: true },
    ];
  },
};

export default nextConfig;
